-- =============================================================================
-- 阶段三：分类规格模板升级为「参数名 + 类型 + 默认值 + 可选值」
-- 执行时机：新版 product-service 上线【后】；旧版解码器只认 string[]，先升级代码再执行本脚本
-- 生成方式：按各叶子分类现有商品 products.specs 里出现过的字段生成模板，
--          取规格项最全的那个商品作为代表，字段值作为默认值，新增商品时自动填入
-- 可重复执行：结果由商品数据决定，重复执行不会产生新的副作用
-- 说明：重量/体积这类纯数字值用 number 控件；其余用 text，管理员可在分类管理里改成 select 并配置可选值
-- =============================================================================

UPDATE categories SET spec_template = '[{"name":"屏幕尺寸","type":"text","defaultValue":"6.9英寸","options":[]},{"name":"处理器","type":"text","defaultValue":"A18 Pro","options":[]},{"name":"运行内存","type":"text","defaultValue":"8GB","options":[]},{"name":"机身存储","type":"text","defaultValue":"256GB/512GB/1TB","options":[]},{"name":"后置摄像头","type":"text","defaultValue":"4800万像素主摄+4800万像素超广角+1200万像素5倍长焦","options":[]},{"name":"防水","type":"text","defaultValue":"IP68","options":[]},{"name":"重量(kg)","type":"number","defaultValue":"","options":[]},{"name":"体积(m³)","type":"number","defaultValue":"","options":[]}]' WHERE id = 101;
