-- 自检：确认模板已是对象数组，而不是历史字符串数组
SELECT COUNT(*) AS object_templates FROM categories
WHERE spec_template IS NOT NULL AND JSON_VALID(spec_template) AND JSON_TYPE(spec_template) = 'ARRAY'
  AND JSON_TYPE(JSON_EXTRACT(spec_template, '$[0]')) = 'OBJECT';
